import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner fs = new Scanner(System.in);
		
		int t = fs.nextInt();
		while (t--> 0) {
		    int n = fs.nextInt();
		    int len = 3 * n;
		    long[] a = new long[3 * n];
		    for (int i = 0; i < 3 * n; ++i) a[i] = fs.nextLong();
		    
		    Arrays.sort(a);
		    for (int i = 0; i < len / 2; ++i) {
		        long tmp = a[i];
		        a[i] = a[len - i - 1];
		        a[len - i - 1] = tmp;
		    }
		  //  for (long x : a) {
		  //      System.out.print(x + " ");
		  //  }
		  //  System.out.println();
		    
		    long[] p = new long[len + 1];
		    for (int i = 0; i < len; ++i) {
		        p[i + 1] = p[i] + a[i];
		    }
		    
		    long ans = 0;
		    
		  //  for (int i = 0; i <= 2 * n; ++i) {
		  //      int x = i / 2, y = i % 2;
		  //      long val = 3 * p[3 * n - i] + p[x + 2 * y] + 2 * p[x];
		  //      ans = Math.max(ans, val);
		  //  }
		  
		    for (int i = 0; i <= n; ++i) {
		        
		        int l = 0, r = n - i;
		        while (r > 4 + l) {
		            int m1 = (r - l) / 3 + l;
		            int m2 = r - (r-l)/3;
		            long v1 = 2 * p[i] + p[i + 2 * m1] + 3 * p[3 * n - 2 * i - m1];
		            long v2 = 2 * p[i] + p[i + 2 * m2] + 3 * p[3 * n - 2 * i - m2];
		            if (v1 < v2) l = m1;
		            else r = m2;
		        }
		        
		        for (int j = l; j <= r; ++j) {
		            long v = 2 * p[i] + p[i + 2 * j] + 3 * p[3 * n - 2 * i - j];
		            ans = Math.max(ans, v);
		        }
		        
		    }
		  
		    
		    System.out.println(ans);
		    
		}

	}
}
